#define KELLY_DECOMP_FULL_FEMENU_ENTRY
#include "KS/SRC/ks/GraphicalMenuSystem_shared.h"
#include "KS/SRC/ks/SoundScript_shared.h"

class BoxText;
class CheatFrontEnd;

class ExtrasFrontEnd : public FEMultiMenu
{
public:
    enum { ExtrasBeachesEntry, ExtrasSurfersEntry, ExtrasTrailersEntry,
           ExtrasHighScoreEntry, ExtrasScrapbookEntry, ExtrasCheatsEntry,
           ExtrasCreditsEntry, ExtrasWebsitesEntry, ExtrasLogbookEntry,
           ExtrasTHDemoEntry, ExtrasDemoEntryYes, ExtrasDemoEntryNo,
           ExtrasEndEntry };

private:
    int cur_index;
    GraphicalMenuSystem* sys;
    FEMenuEntry* entry[ExtrasEndEntry];
    FEMenu* surfers;
    FEMenu* beaches;
    FEMenu* trailers;
    TextString* extras;
    BoxText* prompt;
    BoxText* websites;
    CheatFrontEnd* cheat_menu;
    PanelQuad* videos[ExtrasEndEntry];
    PanelQuad* website_box[9];
    PanelQuad* arrows[2][2];
    bool saveCareerPrompt;
    int arrow_counter;
    int arrow_num;

public:
    virtual void OnTriangle(int c);
};

void ExtrasFrontEnd::OnTriangle(int c)
{
    int i;
    if(active)
        active->OnTriangle(c);
    else
    {
        if (!saveCareerPrompt)
            sys->MakeActive(GraphicalMenuSystem::MainMenu);
#ifdef TARGET_PS2
        else
        {
            for (i=0; i < ExtrasDemoEntryYes; i++)
                entry[i]->Disable(false);
            entry[ExtrasDemoEntryYes]->Disable(true);
            entry[ExtrasDemoEntryNo]->Disable(true);
            saveCareerPrompt = false;
            setHigh(entry[ExtrasTHDemoEntry]);
        }
#endif
        SoundScriptManager::inst()->playEvent(SS_FE_BACK);
    }
}
